WITH not_flagged AS (SELECT s.* FROM sessions s WHERE NOT EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.event_time < s.started_at)) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, MAX(started_at) AS last_seen, COUNT(*) FILTER (WHERE browser = 'Firefox') AS firefox_rows, MAX(started_at) AS ended_at, COUNT_IF(country = 'TH') AS th_events FROM not_flagged GROUP BY DATE_TRUNC('MONTH', started_at) ORDER BY th_events;
